"""Intake scan.css snapshot for server-only email deployments.

Keep byte-identical to web/scan.css; covered by the email layout test.
"""

INTAKE_STYLESHEET = ":root{color-scheme:light;--navy:#101e38;--text:#17243a;--copper:#a65e39;--copper-light:#dda378;--muted:#596578;--pale:#f3f5f7;--line:#d9dfe5;--white:#fff;font-family:'Inter', sans-serif;color:var(--text);background:var(--white);line-height:1.55}*{box-sizing:border-box}body{margin:0}.site-head,main,footer{max-width:1120px;margin:auto;padding-inline:clamp(20px,5vw,64px)}.site-head{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font:12px 'IBM Plex Mono', monospace;letter-spacing:.08em;color:var(--muted)}.brand-mark{display:block;overflow:hidden;width:150px;aspect-ratio:1290/210}.brand-mark img{display:block;width:150px}.hero{padding:clamp(56px,9vw,100px) 0 52px;max-width:850px}.eyebrow,legend span{font:12px 'IBM Plex Mono', monospace;letter-spacing:.12em;color:var(--navy)}h1,h2,h3,legend{font-family:'Archivo', sans-serif;line-height:1.08}h1{font-size:clamp(2.65rem,7vw,5.5rem);letter-spacing:-.035em;margin:18px 0 24px;max-width:14ch}.intro{font-size:clamp(1.08rem,2vw,1.3rem);max-width:62ch;color:var(--muted)}.jump{display:inline-block;margin-top:18px;font-weight:700;color:var(--navy);text-decoration:none}.jump span,button span{color:var(--navy);margin-left:8px}.scope-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;padding:24px 0;border-block:1px solid var(--line);font-size:.9rem;color:var(--muted)}.scope-strip strong{color:var(--text)}form{max-width:820px;padding:54px 0}fieldset{border:0;border-top:1px solid var(--line);padding:42px 0;margin:0}legend{font-size:clamp(1.7rem,4vw,2.4rem);padding-right:20px}legend span{display:inline-block;margin-right:18px}.step-intro{color:var(--muted);max-width:62ch;margin:8px 0 28px}.field{margin:22px 0;max-width:680px}label{display:block;font-weight:650;margin-bottom:7px}label span,small,.note,.test-row p,.draft-note{color:var(--muted);font-weight:400}input,select,textarea,button{font:inherit}input,select,textarea{display:block;width:100%;padding:13px 14px;border:1px solid #8893a3;border-radius:4px;background:var(--white);color:var(--text)}textarea{resize:vertical}small{display:block;margin-top:7px}button{border:1px solid var(--navy);border-radius:4px;background:var(--navy);color:white;padding:13px 20px;font-weight:700;cursor:pointer;min-height:48px}button.secondary{background:white;color:var(--navy)}button:disabled{opacity:.58;cursor:not-allowed}.code-row,.test-row{display:flex;align-items:center;gap:14px}.code-row input{flex:1}.test-row{margin-top:28px}.test-row p{margin:0}.connection{margin-top:24px;border-block:1px solid var(--line);padding:18px 0}summary{cursor:pointer;font-weight:700;color:var(--navy)}.warning{background:var(--pale);padding:22px;margin:24px 0}.warning p{margin:6px 0 0}.legal-note{font-size:.92rem;max-width:72ch}.consent{display:flex;align-items:flex-start;gap:12px;margin:24px 0;max-width:72ch}.consent input{width:21px;flex:0 0 21px;margin-top:3px}.consent a,a{color:var(--navy);text-underline-offset:3px}.draft-note{font-size:.9rem}.error-summary{border:1px solid #a42929;color:#761d1d;padding:16px}.error-summary:empty,#status:empty,#connection-status:empty{display:none}:focus-visible{outline:3px solid var(--navy);outline-offset:3px}footer{border-top:1px solid var(--line);padding-block:28px;margin-top:20px;display:flex;justify-content:space-between;gap:30px;color:var(--muted);font-size:.9rem}footer p{margin:0}@media(max-width:700px){.site-head{height:68px}.site-head span{font-size:10px}.scope-strip{grid-template-columns:1fr 1fr}.hero{padding-top:52px}.code-row,.test-row,footer{align-items:stretch;flex-direction:column}.code-row button,.test-row button{width:100%}fieldset{padding:34px 0}legend span{display:block;margin-bottom:8px}}@media(max-width:420px){.scope-strip{grid-template-columns:1fr}.site-head,main,footer{padding-inline:20px}h1{font-size:2.55rem}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}[hidden]{display:none!important}\n.brand-mark{overflow:visible;width:190px;aspect-ratio:auto}.brand-mark img{width:190px;height:auto}h1,h2,h3,legend{font-weight:400}.jump{display:inline-flex;align-items:center;gap:28px;background:var(--navy);color:var(--white);padding:13px 22px;border-bottom:2px solid var(--navy);min-height:48px}.next-step{border-top:1px solid var(--line);padding-block:40px}.next-step h2{font-size:32px}.data-note{border-top:1px solid var(--line);padding-top:20px}.legal-document{max-width:760px;padding-block:60px}.legal-document h1{font-size:48px;max-width:none}.legal-document h2{font-size:28px;margin-top:36px}.legal-document p{line-height:1.7}.skip-link{position:absolute;left:20px;top:-100px;background:white;padding:12px;z-index:2}.skip-link:focus{top:10px}\n.table-wrap{overflow-x:auto;margin-block:24px}table{border-collapse:collapse;width:100%;min-width:560px}th,td{text-align:left;padding:14px;border-bottom:1px solid var(--line)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--pale);padding:18px}#report>section{padding-block:26px;border-top:1px solid var(--line)}#report h2{font-size:32px}#report h3{font-size:23px}#report details{padding-block:12px}\n"
